/* ── Seeded randomness ─────────────────────────────────────────────────────── */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
export const SEED = 1729;

export interface AtlasNode {
  index: number;
  id: string;
  cluster: ClusterId;
  kind: NodeKind;
  role: string;
  team: string;
  tier: 1 | 2 | 3;
  /** Sample: requests per minute. */
  rpm: number;
  /** Sample: 95th percentile latency, ms. */
  p95: number;
  /** Sample: error rate, percent. */
  errors: number;
  out: number[];
  in: number[];
}
export interface AtlasEdge { index: number; source: number; target: number; cross: boolean }

const TRAFFIC: Record<ClusterId, [number, number]> = { edge: [18000, 60000], identity: [4000, 22000], commerce: [1500, 16000], data: [600, 9000], platform: [900, 30000] };

function build() {
  const rnd = mulberry32(SEED);
  const nodes: AtlasNode[] = RAW.map(([id, cluster, kind, role], index) => {
    const [lo, hi] = TRAFFIC[cluster];
    const rpm = Math.round(Math.exp(Math.log(lo) + rnd() * (Math.log(hi) - Math.log(lo))) / 10) * 10;
    const base = kind === 'store' ? 6 : kind === 'queue' ? 3 : kind === 'external' ? 140 : 18;
    const p95 = Math.round(base * (0.6 + rnd() * 2.4));
    const errors = Math.round((kind === 'external' ? 0.4 + rnd() * 2.2 : rnd() ** 3 * 1.4) * 100) / 100;
    const tier = (cluster === 'edge' || id === 'checkout' || id === 'auth-api' || id === 'payments-adapter' ? 1 : rnd() < 0.5 ? 2 : 3) as 1 | 2 | 3;
    return { index, id, cluster, kind, role, team: CLUSTERS.find((c) => c.id === cluster)!.team, tier, rpm, p95, errors, out: [], in: [] };
  });
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const edges: AtlasEdge[] = EDGES.map(([a, b], index) => {
    const s = byId.get(a), t = byId.get(b);
    if (!s || !t) throw new Error(`atlas: unknown edge ${a} → ${b}`);
    s.out.push(t.index); t.in.push(s.index);
    return { index, source: s.index, target: t.index, cross: s.cluster !== t.cluster };
  });
  return { nodes, edges };
}
export const { nodes: NODES, edges: EDGES_LIST } = build();

/* ── Layout: a small, deterministic force relaxation (3D, or planar for the 2D view) ─────────────────────────── */

export type Layout = Float32Array; // xyz per node

export function relax(planar: boolean, iterations = 420): Layout {
  const rnd = mulberry32(SEED + (planar ? 7 : 3));
  const n = NODES.length;
  const pos = new Float32Array(n * 3), vel = new Float32Array(n * 3);
  const centres = new Map<ClusterId, [number, number, number]>();
  CLUSTERS.forEach((c, i) => {
    const a = (i / CLUSTERS.length) * Math.PI * 2 - Math.PI / 2;
    centres.set(c.id, planar ? [Math.cos(a) * 5.2, -Math.sin(a) * 3.7, 0] : [Math.cos(a) * 4.6, (i % 2 ? 1.2 : -1.1), Math.sin(a) * 4.6]);
  });
  NODES.forEach((node, i) => {
    const c = centres.get(node.cluster)!;
    pos[i * 3] = c[0] + (rnd() - 0.5) * 3;
    pos[i * 3 + 1] = c[1] + (rnd() - 0.5) * 3;
    pos[i * 3 + 2] = planar ? 0 : c[2] + (rnd() - 0.5) * 3;
  });
  const d = [0, 0, 0];
  for (let it = 0; it < iterations; it++) {
    const cool = 1 - it / iterations;
    const force = new Float32Array(n * 3);
    // pairwise repulsion
    for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
      let d2 = 0;
      for (let k = 0; k < 3; k++) { d[k] = pos[i * 3 + k] - pos[j * 3 + k]; d2 += d[k] * d[k]; }
      d2 = Math.max(d2, 0.04);
      const same = NODES[i].cluster === NODES[j].cluster;
      const f = (same ? 0.55 : 1.2) / d2;
      const inv = 1 / Math.sqrt(d2);
      for (let k = 0; k < 3; k++) { force[i * 3 + k] += d[k] * inv * f; force[j * 3 + k] -= d[k] * inv * f; }
    }
    // springs
    for (const e of EDGES_LIST) {
      const i = e.source, j = e.target;
      let d2 = 0;
      for (let k = 0; k < 3; k++) { d[k] = pos[j * 3 + k] - pos[i * 3 + k]; d2 += d[k] * d[k]; }
      const dist = Math.sqrt(Math.max(d2, 1e-6));
      const rest = e.cross ? 3.4 : 1.25;
      const f = (e.cross ? 0.05 : 0.22) * (dist - rest);
      for (let k = 0; k < 3; k++) { force[i * 3 + k] += (d[k] / dist) * f; force[j * 3 + k] -= (d[k] / dist) * f; }
    }
    // cluster gravity + weak centring
    for (let i = 0; i < n; i++) {
      const c = centres.get(NODES[i].cluster)!;
      for (let k = 0; k < 3; k++) force[i * 3 + k] += (c[k] - pos[i * 3 + k]) * 0.16 - pos[i * 3 + k] * 0.012;
    }
    for (let i = 0; i < n * 3; i++) {
      if (planar && i % 3 === 2) continue;
      vel[i] = (vel[i] + Math.max(-1.5, Math.min(1.5, force[i])) * 0.5) * 0.72;
      pos[i] += vel[i] * (0.25 + 0.75 * cool);
    }
  }
  // centre the result
  const mean = [0, 0, 0];
  for (let i = 0; i < n; i++) for (let k = 0; k < 3; k++) mean[k] += pos[i * 3 + k] / n;
  for (let i = 0; i < n; i++) for (let k = 0; k < 3; k++) pos[i * 3 + k] -= mean[k];
  return pos;
}

/** Display radius from traffic (log scale), in scene units. */
export const nodeRadius = (n: AtlasNode): number => 0.2 + 0.3 * Math.min(1, Math.max(0, (Math.log10(n.rpm) - 2.7) / 2.1));

/** Bounding sphere of a layout: centre + radius (including the largest node). */
export function layoutBounds(pos: Layout): { center: [number, number, number]; radius: number } {
  const n = pos.length / 3, c = [0, 0, 0];
  for (let i = 0; i < n; i++) for (let k = 0; k < 3; k++) c[k] += pos[i * 3 + k] / n;
  let r = 0;
  for (let i = 0; i < n; i++) r = Math.max(r, Math.hypot(pos[i * 3] - c[0], pos[i * 3 + 1] - c[1], pos[i * 3 + 2] - c[2]));
  return { center: [c[0], c[1], c[2]], radius: r + 0.5 };
}

/** Cluster colours per theme. Each passes 3:1 against its theme's page background. */
export const PALETTE: Record<'light' | 'dark', Record<ClusterId, string>> = {
  light: { edge: '#c2410c', identity: '#1d4ed8', commerce: '#0f766e', data: '#a16207', platform: '#a21caf' },
  dark: { edge: '#fb8a5c', identity: '#86a8ff', commerce: '#3fc9b4', data: '#e5b648', platform: '#e48ae6' },
};

export const formatRpm = (n: number): string => n.toLocaleString('en-US');

/* Meridian atlas — cartographic paper: a fine survey grid, mono annotations, categorical colour only on data.
   One light from the upper left for the map and the page: shadows fall down and to the right. */
.root { --grid: color-mix(in srgb, var(--mk-ink, #11110f) 7%, transparent); --shade: 44 34 20; }
:global([data-theme='dark']) .root { --shade: 0 0 0; }

.stage {
  position: relative;
  overflow: hidden;
  width: 100%;
  aspect-ratio: 4 / 5;
  max-height: 78svh;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: var(--mk-radius-m, 10px);
  background-color: var(--mk-surface, #fbf9f4);
  background-image:
    linear-gradient(var(--grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid) 1px, transparent 1px);
  background-size: 32px 32px;
  background-position: -1px -1px;
  box-shadow: inset 1px 1px 0 rgb(255 255 255 / 0.6), 2px 3px 0 -1px rgb(var(--shade) / 0.1), 10px 20px 44px -24px rgb(var(--shade) / 0.42);
}
:global([data-theme='dark']) .stage { box-shadow: inset 1px 1px 0 rgb(255 255 255 / 0.05), 10px 20px 44px -24px rgb(0 0 0 / 0.8); }
:global([data-theme='dark']) .stage { background-color: #0e0e0c; }
@container (width >= 40rem) { .stage { aspect-ratio: 16 / 11; } }
.stage canvas:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: -4px; }

.clusterLabel, .nodeLabel {
  position: absolute;
  left: 0;
  top: 0;
  visibility: hidden;
  white-space: nowrap;
  will-change: transform;
}
.clusterLabel {
  font: 600 11px/1 var(--mk-font-mono, ui-monospace, monospace);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 3px 5px;
  background: var(--mk-surface, #fbf9f4);
  border-radius: 3px;
}
:global([data-theme='dark']) .clusterLabel { background: #0e0e0c; }
.nodeLabel {
  margin-top: -4px;
  padding: 3px 6px;
  font: 11.5px/1.1 var(--mk-font-mono, ui-monospace, monospace);
  color: var(--mk-ink, #11110f);
  background: var(--mk-surface, #fbf9f4);
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: 3px;
}
.nodeLabelOn { background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); border-color: var(--mk-ink, #11110f); font-weight: 600; }

.seg {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid var(--mk-line-strong, #11110f);
  font-size: 13px;
  cursor: pointer;
  background: var(--mk-surface, #fbf9f4);
}
.seg:first-of-type { border-radius: 999px 0 0 999px; }
.seg:last-of-type { border-radius: 0 999px 999px 0; margin-left: -1px; }
.seg:has(input:checked) { background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); transform: translateY(1px); box-shadow: inset 1px 1px 3px rgb(0 0 0 / 0.35), 1px 1px 0 rgb(var(--shade) / 0.12); }
.seg:has(input:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; position: relative; z-index: 1; }

.search {
  width: 100%;
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: 999px;
  background: var(--mk-surface, #fbf9f4);
  color: var(--mk-ink, #11110f);
  font: 13.5px var(--mk-font-text, system-ui, sans-serif);
}
.search::placeholder { color: var(--mk-ink-muted, #5c5a52); }

.btn, .pill, .seg {
  /* two shadows: a tight contact edge and a wide soft one; hover lifts (soft grows), press sinks (both collapse) */
  box-shadow: inset 1px 1px 0 rgb(255 255 255 / 0.55), 1px 1.5px 0 rgb(var(--shade) / 0.22), 3px 6px 14px -6px rgb(var(--shade) / 0.32);
  transform: translateY(0);
  transition:
    transform var(--release-dur, 400ms) var(--release-ease, ease),
    box-shadow var(--release-dur, 400ms) var(--release-ease, ease),
    background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
:global([data-theme='dark']) :is(.btn, .pill, .seg) { box-shadow: inset 1px 1px 0 rgb(255 255 255 / 0.07), 1px 1.5px 0 rgb(0 0 0 / 0.6), 3px 6px 14px -6px rgb(0 0 0 / 0.7); }
@media (hover: hover) {
  :is(.btn, .pill:not(:disabled), .seg):hover { transform: translateY(-1.5px); box-shadow: inset 1px 1px 0 rgb(255 255 255 / 0.6), 1px 2.5px 0 rgb(var(--shade) / 0.16), 5px 11px 22px -8px rgb(var(--shade) / 0.4); }
}
:is(.btn, .pill:not(:disabled), .seg):active {
  transform: translateY(1px);
  box-shadow: inset 1px 1px 2px rgb(var(--shade) / 0.18), 0 0 0 rgb(var(--shade) / 0), 1px 2px 4px -2px rgb(var(--shade) / 0.25);
  transition-duration: var(--mk-duration-instant, 90ms);
  transition-timing-function: var(--mk-ease-standard, ease);
}
.root[data-reduced] :is(.btn, .pill, .seg) { transition: none; }
@media (prefers-reduced-motion: reduce) { :is(.btn, .pill, .seg) { transition: none; } }
.btn {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: 999px;
  background: var(--mk-surface, #fbf9f4);
  color: var(--mk-ink, #11110f);
  font-size: 13px;
}
.btn:hover { background: var(--mk-surface-2, #e9e5da); }

.pill {
  min-height: 28px;
  padding: 0 9px;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: 999px;
  background: var(--mk-bg, #f3f0e8);
  color: var(--mk-ink, #11110f);
  font: 12px var(--mk-font-mono, ui-monospace, monospace);
}
.pill:hover:not(:disabled) { border-color: var(--mk-line-strong, #11110f); }
.pill:disabled { color: var(--mk-ink-muted, #5c5a52); text-decoration: line-through; cursor: not-allowed; box-shadow: none; }

.filter {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 36px;
  padding: 0 4px;
  font-size: 14px;
  border-bottom: 1px solid var(--mk-line, #11110f24);
  cursor: pointer;
}
.filter input { width: 16px; height: 16px; accent-color: var(--mk-ink, #11110f); }
.dot { width: 12px; height: 12px; border-radius: 50%; flex: none; }

.tableBox {
  max-height: 460px;
  overflow: auto;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: var(--mk-radius-m, 10px);
  background: var(--mk-surface, #fbf9f4);
}
.table { width: 100%; min-width: 640px; border-collapse: collapse; font-size: 13.5px; }
.table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--mk-surface-2, #e9e5da);
  text-align: left;
  font-weight: 500;
  border-bottom: 1px solid var(--mk-line-strong, #11110f);
}
.table th, .table td { padding: 0 12px; height: 40px; border-bottom: 1px solid var(--mk-line, #11110f24); }
.table tbody th { font-weight: 400; text-align: left; }
.table tbody tr[data-hovered] { background: var(--mk-surface-2, #e9e5da); }
.table tbody tr[data-selected] { background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); }
.table .num { text-align: right; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 12.5px; font-variant-numeric: tabular-nums; }
.table thead .num .sortBtn { justify-content: flex-end; }
.sortBtn {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 6px;
  min-height: 40px;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-size: 12px;
  letter-spacing: 0.02em;
}
.sortMark { font-family: var(--mk-font-mono, ui-monospace, monospace); color: var(--mk-ink-muted, #5c5a52); }
.rowBtn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: 13px var(--mk-font-mono, ui-monospace, monospace);
  text-align: left;
}
.rowBtn[aria-pressed='true'] { font-weight: 700; }

/* The details card keeps one height whatever it shows (nothing, a hover preview, a selection with its neighbour
   lists), so the table below never moves under the pointer; long neighbour lists scroll inside the card. */
.detail { display: flex; flex-direction: column; height: 26rem; }
.detailBody { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.detailLists { flex: 1; min-height: 0; overflow-y: auto; padding: 2px 4px 6px 2px; margin: 0 -4px 0 -2px; }
